"use client";

import {
  LayoutDashboard,
  ClipboardList,
  Syringe,
  AlertTriangle,
  Settings,
} from "lucide-react";
import MobileShell from "../shared/MobileShell";
import VetDashboardHome from "./VetDashboardHome";
import AnimalHealthRecordsPage from "./AnimalHealthRecordsPage";
import TreatmentVaccination from "./Treatment&Vaccination";
import AlertsCriticalCasesPage from "./AlertsCriticalCasesPage";
import SharedSettingsPage from "../shared/SharedSettingsPage";

const vetNav = [
  { label: "Dashboard", key: "dashboard", icon: LayoutDashboard },
  { label: "Animal Health Records", key: "records", icon: ClipboardList },
  { label: "Treatment & Vaccination", key: "treatment", icon: Syringe },
  { label: "Alerts & Critical Cases", key: "alerts", icon: AlertTriangle },
  { label: "Settings", key: "settings", icon: Settings },
];

const pageMap = {
  dashboard: VetDashboardHome,
  records: AnimalHealthRecordsPage,
  treatment: TreatmentVaccinationPage,
  alerts: AlertsCriticalCasesPage,
  settings: () => (
    <div className="px-4 py-4">
      <SharedSettingsPage
        defaultName="Musa Mahmud"
        defaultEmail="limahmud@mail.com"
        defaultPhone="+234 8012 345 678"
        avatarInitials="MM"
      />
    </div>
  ),
};

export default function VetDashboard() {
  return (
    <MobileShell
      navItems={vetNav}
      pageMap={pageMap}
      defaultPage="dashboard"
      greeting="Hi Dr. Musa 👋,"
      user={{ name: "Musa Mahmud", email: "limahmud@mail.com", initials: "MM" }}
    />
  );
}
